import { ComposioToolSet } from "@composio/vercel";
import { generateText } from "ai";
import { openai } from "@ai-sdk/openai";
import * as fs from "fs";

async function main() {
    // Read trial_id
    const trialId = fs.readFileSync("/logs/trial_id", "utf-8").trim();
    const channelName = `agent-results-${trialId}`;
    const userId = "zealt-user01";

    console.log(`Trial ID: ${trialId}`);
    console.log(`Channel Name: ${channelName}`);

    // Initialize Composio ToolSet
    const toolset = new ComposioToolSet({
        apiKey: process.env.COMPOSIO_API_KEY,
    });

    // Get tools for GitHub and Slack for the specific user
    const tools = await toolset.getTools({
        apps: ["github", "slack"],
    }, userId);

    const prompt = `
        1. Fetch the GitHub profile of the user 'composiohq' using the GITHUB_GET_A_USER tool.
        2. Extract the user's 'bio' and 'public_repos' count.
        3. Post a message to a Slack channel named '${channelName}' with the summary: "User composiohq has {public_repos} repos. Bio: {bio}".

        Note: You might need to find the channel ID for '${channelName}' first or use it directly if the tool allows.
    `;

    try {
        const result = await generateText({
            model: openai("gpt-4o"),
            tools: tools,
            prompt: prompt,
            maxSteps: 15,
        });

        console.log("Agent execution completed.");
        console.log("Response:", result.text);
    } catch (error) {
        console.error("Error running agent:", error);
        process.exit(1);
    }
}

